248		result := make([]string, headerMinHeight)
249		for row := 0; row < headerMinHeight; row++ {
250			var line string
251			for ci, colLines := range allColumnLines {
252				if ci > 0 {
253					line += sepRendered
254				}
255				if row < len(colLines) {
256					line += theme.PadWithBg(colLines[row], colWidths[ci])
257				} else {
258					line += theme.EmptyLineBg(colWidths[ci])
259				}
260			}
