283		offset := 1
284		for i := 0; i < headerMinHeight; i++ {
285			logoIdx := i - offset
286			if logoIdx >= 0 && logoIdx < len(logoLines) {
287				lines[i] = theme.PadWithBg(logoStyle.Render(logoLines[logoIdx]), col3Width)
288			} else {
289				lines[i] = theme.EmptyLineBg(col3Width)
290			}
291		}
292		return lines
293	}
