298			return nil
299		}
300	
301		lines := shortcuts.ToStrings()
302	
303		// Find max width for uniform padding
304		maxWidth := 0
305		for _, line := range lines {
306			if w := lipgloss.Width(line); w > maxWidth {
307				maxWidth = w
308			}
309		}
310	
311		// Pad each line to the same width with background
312		var result []string
313		for _, line := range lines {
314			result = append(result, theme.PadWithBg(line, maxWidth))
315		}
316	
317		// Add empty lines if minHeight required
318		for len(result) < minHeight {
319			result = append(result, theme.EmptyLineBg(maxWidth))
320		}
321	
322		return result
323	}
324	
325	func splitArrayIntoChunks(arr []shortcut.Shortcut, chunkSize int) []shortcut.Shortcuts {
326		var chunks []shortcut.Shortcuts
327		for i := 0; i < len(arr); i += chunkSize {
328			end := i + chunkSize
329			if end > len(arr) {
330				end = len(arr)
331			}
332			chunks = append(chunks, arr[i:end])
333		}
334		return chunks
335	}
