337	// commandLineShortcuts is the header's vocabulary while the command line owns
338	// the keyboard. It replaces the view's own: tab and enter stay in place and
339	// grey out when no row is highlighted (Rule 130).
340	func (a *App) commandLineShortcuts() shortcut.Shortcuts {
341		_, runnable := a.runnableText()
342		return shortcut.Shortcuts{
343			{Key: "↑↓", Description: "Choose"},
344			{Key: "tab", Description: "Complete", Disabled: !a.canComplete()},
345			{Key: "enter", Description: "Open", Disabled: !runnable},
346			{Key: "esc", Description: "Close"},
347		}
348	}
